// Command nexus-bench deploys, provisions, inspects and destroys the disposable
// Nexus Community bench of DEVDESK-504 on a k0s cluster. It is a development
// tool driven by the mise tasks nexus-bench:*, outside mise run ci; see
// docs/architecture/nexus-bench.md.
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"syscall"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// Exit codes.
const (
	exitOK      = 0
	exitFailure = 1
	exitUsage   = 2
)

// deps is everything the command needs that reaches a cluster or the network,
// so that the tests run it with fakes. The zero value is enough for render,
// which uses none of it.
type deps struct {
	newRunner  func(kubeContext string) (nexusbench.Runner, error)
	newProber  func() nexusbench.Prober
	clock      nexusbench.Clock
	newStore   func(path string) (nexusbench.SecretStore, error)
	newInitial func(r nexusbench.Runner, namespace string) nexusbench.InitialPassword
	preflight  func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params, op nexusbench.Op) (nexusbench.PreflightResult, error)
	deploy     func(ctx context.Context, r nexusbench.Runner, pr nexusbench.Prober, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) (nexusbench.DeployResult, error)
	provision  func(ctx context.Context, baseURL string, ip nexusbench.InitialPassword, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, error)
	destroy    func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) error

	// NX-02a (DEVDESK-544): the doors of the seed and the reads of status.
	newForwarder   func(kubeContext string) (nexusbench.PortForwarder, error)
	newCopier      func() (nexusbench.ImageCopier, error)
	ensureUpstream func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) error
	seed           func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) (nexusbench.SeedResult, error)
	readUpstream   func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params) (nexusbench.UpstreamState, error)
	readImages     func(ctx context.Context, baseURL, repository string) ([]listedImage, error)

	// NX-02b (DEVDESK-534).
	cutUpstream     func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) error
	restoreUpstream func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) error
	reset           func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, nexusbench.SeedResult, error)
	unblockProxy    func(ctx context.Context, store nexusbench.SecretStore, baseURL string, p nexusbench.Params, out io.Writer) error
}

// defaultDeps wires the real kubectl, HTTP client, clock and files.
func defaultDeps() deps {
	return deps{
		newRunner:  nexusbench.NewExecRunner,
		newProber:  nexusbench.NewProber,
		clock:      nexusbench.NewClock(),
		newStore:   nexusbench.NewFileStore,
		newInitial: nexusbench.NewKubectlInitialPassword,
		preflight:  nexusbench.RunPreflight,
		deploy:     nexusbench.Deploy,
		provision:  nexusbench.Provision,
		destroy:    nexusbench.Destroy,

		newForwarder:   nexusbench.NewExecPortForwarder,
		newCopier:      nexusbench.NewSkopeoCopier,
		ensureUpstream: nexusbench.EnsureUpstream,
		seed:           nexusbench.Seed,
		readUpstream:   nexusbench.ReadUpstream,
		readImages:     readImagesAnonymously,

		cutUpstream:     nexusbench.CutUpstream,
		restoreUpstream: nexusbench.RestoreUpstream,
		reset:           nexusbench.Reset,
		unblockProxy:    nexusbench.UnblockProxy,
	}
}

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	// After the first signal cancels ctx, hand the signals back to the default
	// behavior so that a second Ctrl-C kills a run that is slow to wind down.
	context.AfterFunc(ctx, stop)
	code := run(ctx, os.Args[1:], os.Getenv, os.Stdout, os.Stderr, defaultDeps())
	stop()
	os.Exit(code)
}

// session is one subcommand being run: its context, its resolved parameters and
// its streams.
type session struct {
	ctx    context.Context
	p      nexusbench.Params
	getenv func(string) string
	stdout io.Writer
	stderr io.Writer
	d      deps
	// restHost is where the REST API is reached; explicit tells whether the
	// operator chose it.
	restHost string
	explicit bool
}

// run executes one command line and returns the exit code: 0 for success, 1
// for a failure of the bench, 2 for a mistake in the command line.
func run(ctx context.Context, args []string, getenv func(string) string, stdout, stderr io.Writer, d deps) int {
	if len(args) == 0 {
		printUsage(stderr)
		return exitUsage
	}
	name := args[0]
	switch name {
	case "-h", "--help", "help":
		printUsage(stdout)
		return exitOK
	case "up", "provision", "down", "seed", "status", "render", "cut-upstream", "restore-upstream", "reset":
	default:
		_, _ = fmt.Fprintf(stderr, "nexus-bench: unknown subcommand %q\n\n", name)
		printUsage(stderr)
		return exitUsage
	}

	flags := newFlagSet(name)
	if err := flags.parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printSubcommandHelp(stdout, name, flags)
			return exitOK
		}
		_, _ = fmt.Fprintf(stderr, "nexus-bench %s: %v\nRun nexus-bench %s -h for the flags.\n", name, err, name)
		return exitUsage
	}

	s := &session{ctx: ctx, getenv: getenv, stdout: stdout, stderr: stderr, d: d, restHost: loopbackHost}
	p, err := flags.resolveParams(getenv)
	if err != nil {
		return s.fail(err)
	}
	s.p = p
	if host, given := flags.restHostGiven(); given {
		if err := validateRESTHost(host); err != nil {
			return s.fail(err)
		}
		if (name == "seed" && !isLoopbackHost(host)) || (loopbackOnly(name) && !nexusbench.IsLoopbackRESTHost(host)) {
			return s.fail(fmt.Errorf("%s always reaches Nexus and copies the images through 127.0.0.1, so --rest-host must be a loopback address", name))
		}
		s.restHost, s.explicit = host, true
	}

	switch name {
	case "up":
		return s.up()
	case "provision":
		return s.provision()
	case "down":
		return s.down()
	case "seed":
		return s.seed()
	case "status":
		return s.status()
	case "cut-upstream":
		return s.cutUpstream()
	case "restore-upstream":
		return s.restoreUpstream()
	case "reset":
		return s.reset()
	default:
		return s.render()
	}
}

// fail prints err on stderr and returns the failure code. A BenchError (also
// when wrapped or joined) is printed as its own message and nothing else: the
// text around it and the error it wraps can carry what a sub-process printed,
// a credential included. A cancelled run says so.
func (s *session) fail(err error) int {
	var be *nexusbench.BenchError
	switch {
	case errors.As(err, &be):
		_, _ = fmt.Fprintln(s.stderr, be.Error())
	case errors.Is(err, context.Canceled):
		_, _ = fmt.Fprintln(s.stderr, "cancelled; the cluster keeps what was already done, run nexus-bench status to see it")
	default:
		_, _ = fmt.Fprintln(s.stderr, err.Error())
	}
	return exitFailure
}

// warn prints a warning on stderr.
func (s *session) warn(format string, args ...any) {
	_, _ = fmt.Fprintf(s.stderr, "warning: "+format+"\n", args...)
}

// restURL is the REST origin the credentials are sent to.
func (s *session) restURL() string {
	return nexusbench.RESTBaseURL(s.restHost, s.p)
}

// warnIfClearText says so when the admin credentials leave this machine.
func (s *session) warnIfClearText() {
	if s.explicit && !isLoopbackHost(s.restHost) {
		s.warn("%s is plain HTTP: the credentials travel in clear text to %s", s.restURL(), s.restHost)
	}
}
package main

import (
	"fmt"
	"io"
)

const usageText = `nexus-bench: a disposable Nexus Community bench on a k0s cluster (DEVDESK-504)

Usage: nexus-bench <subcommand> [flags]

Subcommands:
  up         check the cluster, deploy the bench and its upstream registry, wait
             for Nexus, provision it, put docker-proxy back in service when the
             upstream was cut, seed the data set with skopeo and write the
             descriptor
  provision  provision a running Nexus again (idempotent) and write the descriptor
  down       delete the bench namespace and wait until it is gone
  seed       put the data set in a bench that up provisioned (needs skopeo on
             this machine, which mise does not install) and write the descriptor
  status     read the cluster and say how the bench is doing: pod, REST, upstream,
             descriptor, data set (changes nothing)
  render     print the manifests (contacts nothing)
  cut-upstream      scale the bench upstream to zero replicas and wait until no pod
                    is left, so the proxy can only serve what it cached (changes
                    nothing else; no descriptor)
  restore-upstream  bring the upstream back, put the proxy back in service and check
                    the images against the data set (needs skopeo on this machine)
  reset      delete docker-group, docker-proxy, docker-hosted and the upstream
             storage, then provision and seed again: the data set is back to its
             initial state, the pod, the namespace and the passwords are kept
             (needs skopeo on this machine)
  help       print this text

Run nexus-bench <subcommand> -h for the flags of a subcommand. Every flag has a
NEXUS_BENCH_* variable; a flag beats its variable, which beats the default.

Through mise: mise run nexus-bench:up -- --namespace nexus-bench-2

The EULA of Nexus Community Edition is accepted only when you say so
(--accept-eula or NEXUS_BENCH_ACCEPT_EULA=yes); read it first.

Exit codes: 0 success, 1 failure (the cause and what to check are on stderr),
2 mistake in the command line. go run (so mise run nexus-bench:*) does not pass
the code on: it prints "exit status 2" and exits 1. Code 2 is only visible when
the compiled binary is run directly (go build ./internal/nexusbench/cmd/nexus-bench).
`

// printUsage writes the general help to w.
func printUsage(w io.Writer) {
	_, _ = io.WriteString(w, usageText)
}

// subcommandSummary is the line each subcommand help starts with.
var subcommandSummary = map[string]string{
	"up":               "Check the cluster, deploy the bench and its upstream, wait for Nexus, provision it, put docker-proxy back in service when the upstream was cut, seed the data set and write the descriptor. Seeding needs skopeo on this machine (mise does not install it) unless NEXUS_BENCH_UPSTREAM_URL points at an upstream of your own.",
	"provision":        "Provision a running Nexus again (idempotent) and write the descriptor.",
	"down":             "Delete the bench namespace, wait until it is gone, then remove its stored passwords.",
	"seed":             "Put the data set in a bench that up provisioned (images in docker-hosted and in the upstream, one pulled through docker-proxy) and write the descriptor. Needs skopeo on this machine; mise does not install it.",
	"status":           "Read the cluster and the descriptor and report the pod, REST, upstream and data set; nothing is changed.",
	"render":           "Print the manifests for these parameters; the cluster is not contacted.",
	"cut-upstream":     "Scale the bench upstream to zero replicas and wait until no pod of it is left: the proxy then serves only what it cached. Nothing else is changed and the descriptor is not written.",
	"restore-upstream": "Bring the upstream back to one ready replica, put docker-proxy back in service (its configuration is sent again and its cache invalidated) and check the images of the upstream and the cached ones against the data set. Needs skopeo on this machine; mise does not install it.",
	"reset":            "Bring the data set back to its initial state without recreating the instance: delete docker-group, docker-proxy and docker-hosted and replace the claim bench-upstream-data, then provision and seed again and write the descriptor. The Nexus pod, nexus-data, the namespace and the stored passwords are kept. Needs skopeo on this machine; mise does not install it.",
}

// printSubcommandHelp writes the help of one subcommand to w.
func printSubcommandHelp(w io.Writer, name string, flags *flagSet) {
	_, _ = fmt.Fprintf(w, "Usage: nexus-bench %s [flags]\n\n%s\n\nA flag beats its NEXUS_BENCH_* variable, which beats the default.\n\nFlags:\n", name, subcommandSummary[name])
	flags.printHelp(w)
}

