+		case sub != "render" && sub != "record" && !has:
 			t.Errorf("%s reaches the cluster but does not declare kubectl in its tools", name)

package nexusbench

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"mime"
	"net"
	"net/http"
	"net/url"
	"os"
	"path"
