	"github.com/anthnel/devdesk/internal/nexusfixture"
)

// The fixture recorder (DEVDESK-511, step 7). RecordFixtures replays the request
// of each recorded fixture against the bench and writes the redacted answer back
// to the same file. It sends the bench credentials, so everything that could go
// wrong is refused before the first fixture request, and nothing is written
// unless every answer passed: GET only, a closed list of paths, loopback origins
// only, no redirection, a leak check of what will be written.

const (
	// recordedBy is the value of the "recorded-by" header the recorder sets.
	recordedBy = "nexus-bench record"
	// recordedFileMode and recordedDirMode are the modes of a written fixture.
	recordedFileMode os.FileMode = 0o644
	recordedDirMode  os.FileMode = 0o755
	// recordedDateLayout is the date of the "measured" header.
	recordedDateLayout = "2006-01-02"
)

// RecordOptions says what to record and against which bench.
type RecordOptions struct {
	// Origins maps the Host of a fixture ("127.0.0.1:30481") to the base URL that
	// reaches it. Each key must be a loopback host:port of the descriptor and each
	// URL a loopback origin (IsLoopbackRESTHost), no user information. The REST
	// origin (first host of the descriptor, REST node port) is required: the data
	// set is compared through it.
	Origins    map[string]string
	Descriptor Descriptor
	Secrets    Secrets
	// Dir is the folder of the campaigns; empty means nexusfixture.SourceDir().
	Dir string
	// Campaigns limits the run to these campaigns; empty means every folder of Dir.
	Campaigns []string
	// Only is an optional glob (path.Match) on fixture names, without ".http".
	Only string
	// Now gives the date of the "measured" header; nil means time.Now.
	Now func() time.Time
	// DenyTerms are extra terms no written fixture may hold (the external deny list).
	DenyTerms []string
}

// RecordReport lists the fixtures of a run as "<campaign>/<name>". A Skipped
// entry is followed by ": <reason>".
type RecordReport struct {
	Written, Unchanged, Skipped []string
}

// recordJob is one fixture to replay.
type recordJob struct {
	campaign string
	name     string // "<campaign>/<file name without .http>"
	path     string
	current  nexusfixture.Fixture
	user     string // "" for an anonymous fixture
	password string
	origin   string
}

// recordWrite is a fixture file to replace, held back until every answer passed.
type recordWrite struct {
	name string
	path string
	data []byte
}

// RecordFixtures regenerates the recorded fixtures from the bench. A fixture is
// skipped (reported, never requested) when it says "record: skip" or holds more
// than one exchange. A fixture whose answer is the one it already holds, apart
// from its date, is left alone, bytes and modification time. Every error is a
// *BenchError, free of secrets; on an error nothing is written and the report is
// empty.
func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
	if err := ctx.Err(); err != nil {
		return RecordReport{}, recordError("the recording was cancelled before it started", "run it again", err)
	}
	jobs, report, err := planRecording(o)
	if err != nil {
		return RecordReport{}, err
	}
	if len(jobs) > 0 {
		if err := checkBenchDataset(ctx, o); err != nil {
			return RecordReport{}, err
		}
	}
	writes, unchanged, err := gatherAnswers(ctx, o, jobs)
	if err != nil {
		return RecordReport{}, err
	}
	report.Unchanged = unchanged
	for i, w := range writes {
		if err := writeFileAtomic(w.path, w.data, recordedFileMode, recordedDirMode); err != nil {
			return RecordReport{}, recordError(
				fmt.Sprintf("%s could not be written (%d fixture(s) of this run were already written)", w.name, i),
				"check the permissions of the fixtures folder, then record again", err)
		}
		report.Written = append(report.Written, w.name)
	}
	return report, nil
}

// recordError returns a BenchError; err is kept for errors.Is and errors.As and
// is never printed. A refusal with no underlying error keeps its own cause.
func recordError(cause, check string, err error) *BenchError {
	if err == nil {
		err = errors.New(cause)
	}
	return &BenchError{Kind: Unclassified, Cause: cause, Check: check, Err: err}
}

// ---- planning: everything is checked before the first request ------------------

// planRecording reads the fixtures and refuses anything that must not be sent.
func planRecording(o RecordOptions) ([]recordJob, RecordReport, error) {
	var report RecordReport
	if err := checkOrigins(o); err != nil {
		return nil, report, err
	}
	if o.Only != "" {
		if _, err := path.Match(o.Only, ""); err != nil {
			return nil, report, recordError("the fixture filter is not a valid glob", "write it as a path.Match pattern, e.g. catalog-*", err)
		}
	}
	dir := o.Dir
	if dir == "" {
		var err error
		if dir, err = nexusfixture.SourceDir(); err != nil {
			return nil, report, recordError("the fixtures folder of the source tree cannot be located", "run the recorder from a build that knows its source tree (not -trimpath)", err)
		}
	}
	if info, err := os.Stat(dir); err != nil || !info.IsDir() {
		return nil, report, recordError("the fixtures folder "+dir+" is not there", "check the folder", err)
	}
	fsys := os.DirFS(dir)
	campaigns, err := recordCampaigns(dir, fsys, o.Campaigns)
	if err != nil {
		return nil, report, err
	}
	var jobs []recordJob
	for _, campaign := range campaigns {
		entries, err := fs.ReadDir(fsys, campaign)
		if err != nil {
			return nil, report, recordError("the campaign "+campaign+" cannot be read", "check the fixtures folder", err)
		}
		for _, e := range entries {
			name, ok := strings.CutSuffix(e.Name(), ".http")
			if e.IsDir() || !ok {
				continue
			}
			if err := refuseLink(filepath.Join(dir, campaign, e.Name()), campaign+"/"+name); err != nil {
				return nil, report, err
			}
			if o.Only != "" {
				if match, _ := path.Match(o.Only, name); !match {
					continue
				}
			}
			job, skipped, err := planFixture(o, fsys, filepath.Join(dir, campaign, e.Name()), campaign, e.Name())
			switch {
			case err != nil:
				return nil, report, err
			case skipped != "":
				report.Skipped = append(report.Skipped, campaign+"/"+name+": "+skipped)
			default:
				jobs = append(jobs, job)
			}
		}
	}
	return jobs, report, nil
}

// refuseLink refuses a campaign folder or a fixture file that is a symbolic
// link: a link could carry a run, which sends the bench credentials and rewrites
// files, to something that is not in the fixtures folder. A path that cannot be
// inspected is left to the read that follows.
func refuseLink(filePath, label string) error {
	if info, err := os.Lstat(filePath); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return recordError(label+" is a symbolic link", "replace the link with the real file or folder", nil)
	}
	return nil
}

// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
// folder name of fsys (dir on disk), or every folder of fsys. A campaign that is
// a symbolic link is refused, asked for or found.
func recordCampaigns(dir string, fsys fs.FS, wanted []string) ([]string, error) {
	if len(wanted) == 0 {
		entries, err := fs.ReadDir(fsys, ".")
		if err != nil {
			return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
		}
		var all []string
		for _, e := range entries {
			if strings.HasPrefix(e.Name(), ".") {
				continue
			}
			if e.Type()&fs.ModeSymlink != 0 {
				return nil, recordError("the campaign "+e.Name()+" is a symbolic link", "replace the link with the real folder", nil)
			}
			if e.IsDir() {
				all = append(all, e.Name())
			}
		}
		return all, nil
	}
	for _, c := range wanted {
		if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
			return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
		}
		if err := refuseLink(filepath.Join(dir, c), c); err != nil {
			return nil, err
		}
		if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
			return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
		}
	}
	return wanted, nil
}

// planFixture reads one fixture file. It returns the reason when the fixture is
// skipped, an error when it must not be sent.
func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
	label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
	data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
	if err != nil {
		return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
	}
	f, err := nexusfixture.Parse(campaign, fileName, data)
	if err != nil {
		return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file", err)
	}
	if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
		return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
	}
	if len(f.Exchanges) != 1 {
		return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
	}
	// The file is scanned as it stands: a request header outside Host, the
	// credentials and Accept, or a query other than n and last, refuses it.
	if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
		return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
	}
	ex := f.Exchanges[0]
	if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
		return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
	}
	origin, ok := o.Origins[ex.Host]
	if !ok {
		return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
	}
	job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
	switch f.Identity {
	case nexusfixture.Admin:
		job.user, job.password = REDACTED, o.Secrets.AdminPassword
	case nexusfixture.Pull:
		job.user, job.password = REDACTED, o.Secrets.PullPassword
	}
	if job.user != "" && job.password == "" {
		return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
	}
	return job, "", nil
}

// checkOrigins refuses an origin that is not a loopback URL, a key that is not a
// loopback host:port of the descriptor, and a run with no REST origin.
func checkOrigins(o RecordOptions) error {
	known := descriptorOrigins(o.Descriptor)
	for key, base := range o.Origins {
		if !known[key] {
			return recordError("the origin of "+key+" is not a loopback host:port of the bench descriptor", "give origins for the hosts and ports the descriptor lists", nil)
		}
		if err := requireLoopbackBase(base); err != nil {
			return err
		}
	}
	rest, ok := restOriginKey(o.Descriptor)
	if _, have := o.Origins[rest]; !ok || !have {
		return recordError("no origin is given for the REST port of the bench, which the data set check needs", "give the REST origin of the descriptor", nil)
	}
	return nil
}

// descriptorOrigins is the set of loopback host:port pairs the descriptor
// publishes: every host of the descriptor on the REST and the Docker ports.
func descriptorOrigins(d Descriptor) map[string]bool {
	ports := []int{d.REST.NodePort}
	for _, c := range d.DockerConnectors {
		ports = append(ports, c.NodePort)
	}
	known := map[string]bool{}
	for _, h := range d.Hosts {
		host := strings.Trim(h, "[]")
		if !IsLoopbackRESTHost(host) {
			continue
		}
		for _, p := range ports {
			known[net.JoinHostPort(host, strconv.Itoa(p))] = true
		}
	}
	return known
}

// restOriginKey is the host:port of the REST API: the first host of the
// descriptor on the REST node port.
func restOriginKey(d Descriptor) (string, bool) {
	if len(d.Hosts) == 0 || d.REST.NodePort == 0 {
		return "", false
	}
	return net.JoinHostPort(strings.Trim(d.Hosts[0], "[]"), strconv.Itoa(d.REST.NodePort)), true
}

// The closed list of what the recorder may ask for. A manifest or a blob read
// through a proxy repository would cache an image and change the bench, so none
// is allowed, whatever the path says.
var (
	recordPaths = []*regexp.Regexp{
		regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
		regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
		regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
	}
	recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=[A-Za-z0-9._/-]*)$`)
)

// refusedRequest returns why a request may not be sent, or "".
func refusedRequest(method, target string) string {
	p, query, hasQuery := strings.Cut(target, "?")
	switch {
	case method != http.MethodGet:
		return "the method is not GET"
	case strings.Contains(target, "..") || strings.Contains(target, "%"):
		return "the target holds a dot-dot or an escape"
	case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
		return "a manifest or a blob read can change the bench"
	}
	listed := false
	for _, re := range recordPaths {
		listed = listed || re.MatchString(p)
	}
	if !listed {
		return "the path is not in the closed list"
	}
	if hasQuery {
		for _, param := range strings.Split(query, "&") {
			if !recordQueryParam.MatchString(param) {
				return "the query holds more than n and last"
			}
		}
	}
	return ""
}

// ---- the data set of the bench ---------------------------------------------------

// checkBenchDataset compares, anonymously, what docker-hosted and docker-proxy
// list with the data set of the descriptor: a bench that does not hold it would
// record answers that are not the ones the fixtures describe. What cannot be read
// is a refusal too.
func checkBenchDataset(ctx context.Context, o RecordOptions) error {
	if len(o.Descriptor.Dataset) == 0 {
		return recordError("the descriptor lists no data set to compare the bench with", "run `mise run nexus-bench:seed`", nil)
	}
	key, _ := restOriginKey(o.Descriptor)
	base := o.Origins[key]
	for _, repo := range DatasetRepositories() {
		listed, err := ListImagesAnonymously(ctx, base, repo)
		if err != nil {
			return recordError("the listing of "+repo+" could not be read, so the data set of the bench is unknown",
				"check that the bench answers and that anonymous access is on", err)
		}
		diffs, ok := CompareDataset(DatasetIn(o.Descriptor.Dataset, repo), listed)
		if !ok {
			return recordError("the listing of "+repo+" gives no digest, so the data set of the bench cannot be compared", resetCheck, nil)
		}
		if diffs > 0 {
			return recordError(fmt.Sprintf("%s differs from the data set of the descriptor (%d image(s))", repo, diffs), resetCheck, nil)
		}
	}
	return nil
}

// DatasetRepositories are the two repositories that hold the data set. The group
// is never read: a read through it can cache an image.
func DatasetRepositories() []string {
	return []string{dockerHostedRepository, dockerProxyRepository}
}

// DatasetIn returns the images of the data set that repo holds: the hosted ones
// in docker-hosted, the ones cached in the proxy in docker-proxy.
func DatasetIn(images []DescriptorImage, repo string) []DescriptorImage {
	var out []DescriptorImage
	for _, img := range images {
		hosted := repo == dockerHostedRepository && img.Location == string(LocationHosted)
		cached := repo == dockerProxyRepository && img.CachedInProxy
		if hosted || cached {
			out = append(out, img)
		}
	}
	return out
}

// CompareDataset counts the images of a repository that are missing, have
// another digest, or are not in the data set. ok is false when the listing gives
// no digest for an image that is there, which makes the comparison impossible.
func CompareDataset(want []DescriptorImage, listed []ListedImage) (diffs int, ok bool) {
	have := make(map[string]string, len(listed))
	for _, img := range listed {
		have[img.Name+":"+img.Tag] = img.Digest
	}
	for _, img := range want {
		key := img.Name + ":" + img.Tag
		digest, found := have[key]
		delete(have, key)
		switch {
		case !found:
			diffs++
		case digest == "":
			return 0, false
		case digest != img.Digest:
			diffs++
		}
	}
	return diffs + len(have), true
}

// ---- gathering the answers ------------------------------------------------------

// gatherAnswers asks every job and returns the files to write and the fixtures
// that did not change. The first problem ends the run: nothing is written yet.
func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged []string, err error) {
	clients := map[string]*client{}
	defer func() {
		for _, c := range clients {
			c.closeIdle()
		}
	}()
	now := time.Now
	if o.Now != nil {
		now = o.Now
	}
	date := now().Format(recordedDateLayout)
	for _, j := range jobs {
		key := j.origin + "\x00" + j.user
		c, ok := clients[key]
		if !ok {
			c = newClient(j.origin, j.user, j.password)
			clients[key] = c
		}
		data, same, err := j.record(ctx, o, c, date)
		switch {
		case err != nil:
			return nil, nil, err
		case same:
			unchanged = append(unchanged, j.name)
		default:
			writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
		}
	}
	return writes, unchanged, nil
}

// record asks the bench for the answer of the job and returns the bytes of the
// fixture it would write; same is true when the file already holds that answer.
func (j recordJob) record(ctx context.Context, o RecordOptions, c *client, date string) (data []byte, same bool, err error) {
	ex := j.current.Exchanges[0]
	status, header, body, err := c.exchange(ctx, ex.Method, ex.Target, ex.RequestHeader)
	if err != nil {
		return nil, false, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
	}
	if !benchVersionMatches(header.Get("Server"), o.Descriptor) {
		return nil, false, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", upCheck, nil)
	}
	if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
		return nil, false, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
	}
	answer := nexusfixture.Redact(nexusfixture.RawExchange{
		Method: ex.Method, Target: ex.Target, Host: ex.Host, RequestHeader: ex.RequestHeader,
		Status: status, Header: header, Body: body,
	})
	if answer.Stub == "" && answer.Header.Get("Content-Length") != "" {
		// A redacted body is not as long as the one Nexus sent.
		answer.Header.Set("Content-Length", strconv.Itoa(len(answer.Body)))
	}
	f := j.current
	f.Meta.NexusVersion, f.Meta.Edition, f.Meta.NexusNote = o.Descriptor.NexusVersion, o.Descriptor.Edition, ""
	f.Meta.Measured, f.Meta.RecordedBy = date, recordedBy
	if f.Meta.Record == nexusfixture.RecordPending {
		f.Meta.Record = ""
	}
	f.Exchanges = []nexusfixture.Exchange{answer}
	data = nexusfixture.Format(f)

	// What will be written is read back and checked, not what was built.
	back, err := nexusfixture.Parse(j.campaign, filepath.Base(j.path), data)
	if err != nil || !bytes.Equal(nexusfixture.Format(back), data) {
		return nil, false, recordError("the answer to "+j.name+" does not read back as a fixture", "do not record this answer", err)
	}
	if leaks := nexusfixture.CheckLeaks(j.name, data, recordTerms(o)); len(leaks) > 0 {
		return nil, false, recordError("the answer to "+j.name+" would leak: "+describeLeaks(leaks), "nothing was written; fix the bench or the redaction", nil)
	}
	if holdsTerm(header, body, recordTerms(o)) {
		return nil, false, recordError("the answer to "+j.name+" holds a bench password or a denied term where the file would not show it", "nothing was written; do not record this answer", nil)
	}
	return data, sameAnswer(j.current, f), nil
}

// sameAnswer reports whether the file already holds the answer: the same
// exchange under the same version and edition. The date, the notes and who
// recorded it do not count.
func sameAnswer(current, recorded nexusfixture.Fixture) bool {
	if current.Meta.NexusVersion != recorded.Meta.NexusVersion || current.Meta.Edition != recorded.Meta.Edition {
		return false
	}
	text := func(ex nexusfixture.Exchange) []byte {
		return nexusfixture.Format(nexusfixture.Fixture{Exchanges: []nexusfixture.Exchange{ex}})
	}
	return bytes.Equal(text(current.Exchanges[0]), text(recorded.Exchanges[0]))
}

var serverHeader = regexp.MustCompile(`^Nexus/(\S+) \(([A-Za-z]+)\)$`)

// benchVersionMatches reports whether a Server header names the version and the
// edition of the descriptor.
func benchVersionMatches(server string, d Descriptor) bool {
	m := serverHeader.FindStringSubmatch(server)
	return m != nil && m[1] == d.NexusVersion && m[2] == d.Edition
}

// declaresJSON reports whether a Content-Type is JSON.
func declaresJSON(contentType string) bool {
	media, _, err := mime.ParseMediaType(contentType)
	return err == nil && (media == "application/json" || strings.HasSuffix(media, "+json"))
}

// ---- leaks ------------------------------------------------------------------------

// recordTerms are the terms no written fixture may hold: the bench passwords,
// their Basic encodings, and the external deny list.
func recordTerms(o RecordOptions) []string {
	terms := append([]string(nil), o.DenyTerms...)
	for _, account := range []struct{ user, password string }{
		{REDACTED, o.Secrets.AdminPassword},
		{REDACTED, o.Secrets.PendingAdminPassword},
		{REDACTED, o.Secrets.PullPassword},
	} {
		if account.password == "" {
			continue
		}
		terms = append(terms, account.password,
			base64.StdEncoding.EncodeToString([]byte(account.user+":"+account.password)))
	}
	return terms
}

// describeLeaks names the rules and the lines of a leak report, never what matched.
func describeLeaks(leaks []nexusfixture.Leak) string {
	parts := make([]string, 0, len(leaks))
	for _, l := range leaks {
		parts = append(parts, fmt.Sprintf("%s at line %d", l.Rule, l.Line))
	}
	return strings.Join(parts, ", ")
}

// holdsTerm searches the raw answer, whatever the redaction would drop or hide
// (a header outside the allowlist, an HTML body), for a term in the forms it can
// take: as is, in another case, URL-escaped, JSON-escaped.
func holdsTerm(header http.Header, body []byte, terms []string) bool {
	var raw strings.Builder
	for name, values := range header {
		raw.WriteString(name + ": " + strings.Join(values, "\n") + "\n")
	}
	raw.Write(body)
	text := strings.ToLower(raw.String())
	jsonEscaper := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
	for _, term := range terms {
		if term == "" {
			continue
		}
		for _, v := range []string{term, url.QueryEscape(term), url.PathEscape(term), jsonEscaper.Replace(term)} {
			if strings.Contains(text, strings.ToLower(v)) {
				return true
			}
		}
	}
	return false
}

package main

import (
	"flag"
	"fmt"
	"io"
	"net/netip"
	"regexp"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// Defaults of the flags that are not a NEXUS_BENCH_* parameter.
const (
	loopbackHost = "127.0.0.1"
	maxHostLen   = 253
)

var (
	// hostName is a DNS name: letters, digits, '.' and '-', no port, no path,
	// no credentials, no whitespace.
	hostName = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
	// ipv6Zone is the zone of a link-local address ("eth0" in fe80::1%eth0).
	ipv6Zone = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
)

// flagKind is the type of a flag, which decides how it is registered and how
// its value is handed to nexusbench.FromEnv.
type flagKind int

const (
	kindString flagKind = iota
	kindInt
	kindDuration
	kindBool
	// kindConsent is a boolean whose true is the exact word "yes", the only
	// value nexusbench accepts for NEXUS_BENCH_ACCEPT_EULA.
	kindConsent
)

// paramFlag is one flag that stands for one NEXUS_BENCH_* variable.
type paramFlag struct {
	name  string
	env   string
	kind  flagKind
	usage string
}

// commonFlags are accepted by every subcommand.
func commonFlags() []paramFlag {
	d := nexusbench.Defaults()
	return []paramFlag{
		{"context", "NEXUS_BENCH_CONTEXT", kindString, "kubectl context of the cluster (default " + d.Context + ")"},
		{"namespace", "NEXUS_BENCH_NAMESPACE", kindString, "namespace of the bench, which down deletes (default " + d.Namespace + ")"},
		{"http-nodeport", "NEXUS_BENCH_HTTP_NODEPORT", kindInt, fmt.Sprintf("NodePort of the REST API and the UI (default %d)", d.HTTPNodePort)},
		{"docker-nodeport", "NEXUS_BENCH_DOCKER_NODEPORT", kindInt, fmt.Sprintf("NodePort of the Docker connector (default %d)", d.DockerNodePort)},
		{"cpu-request", "NEXUS_BENCH_CPU_REQUEST", kindString, "CPU request (default " + d.CPURequest + ")"},
		{"cpu-limit", "NEXUS_BENCH_CPU_LIMIT", kindString, "CPU limit (default " + d.CPULimit + ")"},
		{"memory-request", "NEXUS_BENCH_MEMORY_REQUEST", kindString, "memory request (default " + d.MemoryRequest + ")"},
		{"memory-limit", "NEXUS_BENCH_MEMORY_LIMIT", kindString, "memory limit (default " + d.MemoryLimit + ")"},
		{"storage-size", "NEXUS_BENCH_STORAGE_SIZE", kindString, "size of the data volume (default " + d.StorageSize + ")"},
		{"jvm-opts", "NEXUS_BENCH_JVM_OPTS", kindString, "JVM options of Nexus (default " + d.JVMOpts + ")"},
		{"image", "NEXUS_BENCH_IMAGE", kindString, "Nexus image, without the tag (default " + d.Image + ")"},
		{"image-tag", "NEXUS_BENCH_IMAGE_TAG", kindString, "Nexus image tag (default " + d.ImageTag + ")"},
		{"upstream-image", "NEXUS_BENCH_UPSTREAM_IMAGE", kindString, "image of the bench upstream registry, without the tag (default " + d.UpstreamImage + ")"},
		{"upstream-image-tag", "NEXUS_BENCH_UPSTREAM_IMAGE_TAG", kindString, "tag of the bench upstream registry image (default " + d.UpstreamImageTag + ")"},
		{"upstream-url", "NEXUS_BENCH_UPSTREAM_URL", kindString, "upstream of the proxy repository (default http://bench-upstream.<namespace>.svc.cluster.local:5000)"},
		{"anonymous", "NEXUS_BENCH_ANONYMOUS", kindBool, "enable anonymous access, --anonymous=false to disable (default true)"},
		{"hosts", "NEXUS_BENCH_HOSTS", kindString, "comma-separated hosts the NodePorts are tried on (default 127.0.0.1 and the node address)"},
		{"timeout", "NEXUS_BENCH_TIMEOUT", kindDuration, "how long up waits for Nexus, and how long the seed may run (default " + d.Timeout.String() + ")"},
		{"delete-timeout", "NEXUS_BENCH_DELETE_TIMEOUT", kindDuration, "how long down waits for the namespace to go (default " + d.DeleteTimeout.String() + ")"},
		{"secrets", "NEXUS_BENCH_SECRETS", kindString, "secrets file, outside the repository (default under $XDG_STATE_HOME/devdesk/nexus-bench)"},
		{"descriptor", "NEXUS_BENCH_DESCRIPTOR", kindString, "descriptor file (default internal/nexusbench/descriptor.json)"},
	}
}

// provisionFlags are accepted by the subcommands that provision Nexus.
func provisionFlags() []paramFlag {
	return []paramFlag{
		{"accept-eula", "NEXUS_BENCH_ACCEPT_EULA", kindConsent, "accept the Nexus Community Edition EULA on your behalf: read it first (default false; the variable counts only as the exact value yes)"},
	}
}

// restHostFlag names the flag that picks the host the admin credentials are sent to.
const restHostFlag = "rest-host"

// flagSet is the flags of one subcommand.
type flagSet struct {
	fs       *flag.FlagSet
	specs    map[string]paramFlag
	restHost *string
}

// newFlagSet registers the flags of a subcommand. It prints nothing by itself:
// the caller reports a parse error on stderr and the help on stdout.
func newFlagSet(name string) *flagSet {
	// up and provision provision Nexus (EULA); they and seed send the admin
	// credentials to the REST API (REST host).
	provisions := name == "up" || name == "provision"
	reachesREST := provisions || name == "seed" || loopbackOnly(name)
	fs := flag.NewFlagSet("nexus-bench "+name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	set := &flagSet{fs: fs, specs: map[string]paramFlag{}}
	specs := commonFlags()
	if provisions {
		specs = append(specs, provisionFlags()...)
	}
	for _, spec := range specs {
		set.specs[spec.name] = spec
		switch spec.kind {
		case kindString:
			fs.String(spec.name, "", spec.usage)
		case kindInt:
			fs.Int(spec.name, 0, spec.usage)
		case kindDuration:
			fs.Duration(spec.name, time.Duration(0), spec.usage)
		case kindBool, kindConsent:
			fs.Bool(spec.name, false, spec.usage)
		}
	}
	switch {
	case name == "seed" || loopbackOnly(name):
		// These refuse another host (main.go): their credentials and their images
		// always go through the loopback.
		set.restHost = fs.String(restHostFlag, "", "loopback address the REST API is reached on (default "+loopbackHost+"); "+name+" accepts a loopback address only, because its images and the admin credentials always go through "+loopbackHost)
	case reachesREST:
		set.restHost = fs.String(restHostFlag, "", "host the REST API is reached on, and so the host the admin credentials are sent to (default "+loopbackHost+"); another host sends them in clear text. It concerns the REST API only: the images always go through "+loopbackHost)
	}
	return set
}

// parse reads args. It returns flag.ErrHelp for -h and --help, and an error for
// an unknown flag, a value of the wrong type or an argument that is not a flag.
func (s *flagSet) parse(args []string) error {
	if err := s.fs.Parse(args); err != nil {
		return err
	}
	if s.fs.NArg() > 0 {
		return fmt.Errorf("unexpected argument %q", s.fs.Arg(0))
	}
	return nil
}

// printHelp writes the flags and their default to w.
func (s *flagSet) printHelp(w io.Writer) {
	s.fs.SetOutput(w)
	s.fs.PrintDefaults()
	s.fs.SetOutput(io.Discard)
}

// overlay returns getenv with every flag that was given laid over its
// NEXUS_BENCH_* variable: nexusbench.FromEnv then applies "flag, then variable,
// then default" in one place, with the same parsing and the same follow-the-
// namespace rule for the upstream URL.
func (s *flagSet) overlay(getenv func(string) string) func(string) string {
	given := map[string]string{}
	s.fs.Visit(func(f *flag.Flag) {
		spec, ok := s.specs[f.Name]
		if !ok {
			return
		}
		value := f.Value.String()
		if spec.kind == kindConsent {
			value = map[bool]string{true: "yes", false: "no"}[value == "true"]
		}
		given[spec.env] = value
	})
	return func(name string) string {
		if v, ok := given[name]; ok {
			return v
		}
		return getenv(name)
	}
}

// restHostGiven returns the --rest-host value and whether it was set.
func (s *flagSet) restHostGiven() (string, bool) {
	if s.restHost == nil {
		return "", false
	}
	given := false
	s.fs.Visit(func(f *flag.Flag) {
		if f.Name == restHostFlag {
			given = true
		}
	})
	return *s.restHost, given
}

// resolveParams returns the validated parameters of a run: defaults, then the
// NEXUS_BENCH_* variables, then the flags.
func (s *flagSet) resolveParams(getenv func(string) string) (nexusbench.Params, error) {
	p, err := nexusbench.FromEnv(nexusbench.Defaults(), s.overlay(getenv))
	if err != nil {
		return p, err
	}
	return p, p.Validate()
}

// validateRESTHost refuses what is not a host name or an IP address: a port, a
// path, a scheme, credentials or whitespace would change where the admin
// credentials go.
func validateRESTHost(host string) error {
	if host == "" || len(host) > maxHostLen {
		return fmt.Errorf("--%s: %q is not a host name or an IP address", restHostFlag, host)
	}
	if addr, ok := hostAddress(host); ok {
		if zone := addr.Zone(); zone != "" && !ipv6Zone.MatchString(zone) {
			return fmt.Errorf("--%s: %q has an unusable IPv6 zone", restHostFlag, host)
		}
		return nil
	}
	if !hostName.MatchString(host) {
		return fmt.Errorf("--%s: %q is not a host name or an IP address (no port, scheme, path or credentials)", restHostFlag, host)
	}
	return nil
}

// hostAddress parses host as an IP address, with or without the brackets of an
// IPv6 literal.
func hostAddress(host string) (netip.Addr, bool) {
	if len(host) > 1 && strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
		host = host[1 : len(host)-1]
	}
	addr, err := netip.ParseAddr(host)
	return addr, err == nil
}

// loopbackOnly tells whether a subcommand sends the admin credentials and its
// images through the loopback and nowhere else.
func loopbackOnly(name string) bool { return name == "restore-upstream" || name == "reset" }

// isLoopbackHost tells whether host stays on this machine.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	addr, ok := hostAddress(host)
	return ok && addr.Unmap().IsLoopback()
}
package main

import (
	"context"
	"errors"
	"fmt"
	"reflect"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// render prints the manifests. It builds no dependency: it contacts nothing.
func (s *session) render() int {
	out, err := nexusbench.Render(s.p)
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.stdout.Write(out); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// open resolves the secrets path and builds the runner and the store, in that
// order, before anything touches the cluster. Both are refused here when they
// cannot work: kubectl missing, a secrets path that git does not ignore.
func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
	if s.p.SecretsPath == "" {
		path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
		if err != nil {
			return nil, nil, err
		}
		s.p.SecretsPath = path
	}
	runner, err := s.d.newRunner(s.p.Context)
	if err != nil {
		return nil, nil, err
	}
	store, err := s.d.newStore(s.p.SecretsPath)
	if err != nil {
		return nil, nil, err
	}
	return runner, store, nil
}

// doors are the two doors the seed goes through besides kubectl: the
// port-forward to the upstream and the image copier.
type doors struct {
	forwarder nexusbench.PortForwarder
	copier    nexusbench.ImageCopier
}

// openDoors builds the doors of the seed, the forwarder first. They are built
// before anything touches the cluster: a host without skopeo is refused here,
// not after the deployment.
func (s *session) openDoors() (doors, error) {
	forwarder, err := s.d.newForwarder(s.p.Context)
	if err != nil {
		return doors{}, err
	}
	copier, err := s.d.newCopier()
	if err != nil {
		return doors{}, err
	}
	return doors{forwarder: forwarder, copier: copier}, nil
}

// bounded runs fn with a context that ends after Params.Timeout, counted from
// now, so that a call over a port-forward that hangs does not hang the command.
// A call that outlasts it is a failure with its own message; a cancelled run keeps
// the plain cancellation. what names the call ("the seed"), and advice is what to
// run next.
func (s *session) bounded(what, advice string, fn func(ctx context.Context) error) error {
	ctx, cancel := s.ctx, context.CancelFunc(func() {})
	if s.p.Timeout > 0 {
		ctx, cancel = context.WithTimeout(s.ctx, s.p.Timeout)
	}
	defer cancel()
	err := fn(ctx)
	if err != nil && ctx.Err() != nil && s.ctx.Err() == nil {
		return &nexusbench.BenchError{
			Kind:  nexusbench.Deadline,
			Cause: fmt.Sprintf("%s did not finish within %s", what, s.p.Timeout),
			Check: "raise --timeout (NEXUS_BENCH_TIMEOUT) and " + advice,
			Err:   err,
		}
	}
	return err
}

// seedDeps are what the library calls that copy or read through the doors need.
func (s *session) seedDeps(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) nexusbench.SeedDeps {
	return nexusbench.SeedDeps{Runner: runner, Forwarder: d.forwarder, Copier: d.copier, Clock: s.d.clock, Store: store}
}

// runSeed runs Seed under the timeout.
func (s *session) runSeed(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) (nexusbench.SeedResult, error) {
	var res nexusbench.SeedResult
	err := s.bounded("the seed", "run nexus-bench seed again: the images already copied are kept", func(ctx context.Context) (err error) {
		res, err = s.d.seed(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
		return err
	})
	if err != nil {
		return nexusbench.SeedResult{}, err
	}
	return res, nil
}

// cutUpstream scales the upstream to zero. It needs no store and no door: the
// preflight of a cut asks for what a scale needs.
func (s *session) cutUpstream() int {
	runner, _, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpCut); err != nil {
		return s.fail(err)
	}
	if err := s.d.cutUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// restoreUpstream brings a cut upstream back. It writes no descriptor.
func (s *session) restoreUpstream() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpRestore); err != nil {
		return s.fail(err)
	}
	err = s.bounded("the restore", "run `mise run nexus-bench:restore-upstream` again", func(ctx context.Context) error {
		return s.d.restoreUpstream(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
	})
	if err != nil {
		return s.fail(err)
	}
	return exitOK
}

// reset puts the data set back to its initial state. Reset runs its own
// preflight; the descriptor of the previous run is read before anything is
// deleted and written again after a reset that succeeded, with the hosts of the
// previous one (the preflight of a reset reads no node).
func (s *session) reset() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	prev, err := s.previousDescriptor()
	if err != nil {
		return s.fail(err)
	}
	var provisioned nexusbench.ProvisionResult
	var seeded nexusbench.SeedResult
	err = s.bounded("the reset", "run `mise run nexus-bench:reset` again: it starts over", func(ctx context.Context) (err error) {
		provisioned, seeded, err = s.d.reset(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
		return err
	})
	if errors.Is(err, context.Canceled) {
		// The library returns the cancellation as is, and a reset stopped after its
		// first deletion leaves a half-deleted data set.
		_, _ = fmt.Fprintln(s.stderr, "cancelled; the data set may be half deleted, run `mise run nexus-bench:reset` again: it starts over")
		return exitFailure
	}
	if err != nil {
		return s.fail(err)
	}
	return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
}

// up deploys the bench and the upstream, provisions Nexus, seeds the data set
// and only then writes the descriptor (D-J). Deploy runs the preflight of up
// itself. An upstream URL the bench did not deploy is left alone: nothing is
// scaled or seeded, and the data set is described as empty.
func (s *session) up() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	seeds := s.p.UpstreamIsBench()
	var d doors
	if seeds {
		if d, err = s.openDoors(); err != nil {
			return s.fail(err)
		}
	}
	s.warnIfClearText()
	deployed, err := s.d.deploy(s.ctx, runner, s.d.newProber(), s.d.clock, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	cut := false
	if seeds {
		if cut, err = s.foundCut(runner); err != nil {
			return s.fail(err)
		}
		if err := s.d.ensureUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
			return s.fail(err)
		}
	}
	provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	if cut {
		if err := s.d.unblockProxy(s.ctx, store, s.restURL(), s.p, s.stdout); err != nil {
			return s.fail(retryRestore(err))
		}
	}
	var seeded nexusbench.SeedResult
	if seeds {
		if seeded, err = s.runSeed(runner, store, d); err != nil {
			return s.fail(err)
		}
	} else {
		_, _ = fmt.Fprintln(s.stdout, "seed: skipped, NEXUS_BENCH_UPSTREAM_URL points at an upstream the bench did not deploy, so there is nothing to fill")
	}
	return s.writeDescriptor(deployed, provisioned, seeded)
}

// retryRestore tells, in the check of a BenchError, that the proxy is still
// blocked and that a second up will not unblock it: the upstream is back by now,
// so the second up finds it ready. Another error is returned as it is.
func retryRestore(err error) error {
	var be *nexusbench.BenchError
	if !errors.As(err, &be) {
		return err
	}
	return &nexusbench.BenchError{
		Kind:  be.Kind,
		Cause: be.Cause,
		Check: be.Check + "; the upstream is back but docker-proxy is still blocked, and a second up will not retry that: run `mise run nexus-bench:restore-upstream`",
		Err:   be.Err,
	}
}

// foundCut reads the upstream before EnsureUpstream brings it back, and tells
// whether it was cut: the proxy then needs to be unblocked (D-Q). The proxy can
// only be unblocked through the loopback; with another REST host, up stops here,
// before it brings the upstream back, because a refusal later would leave a proxy
// that stays blocked (a second up finds the upstream ready).
func (s *session) foundCut(runner nexusbench.Runner) (bool, error) {
	state, err := s.d.readUpstream(s.ctx, runner, s.p)
	if err != nil {
		return false, err
	}
	if state != nexusbench.UpstreamCut {
		return false, nil
	}
	if !nexusbench.IsLoopbackRESTHost(s.restHost) {
		return false, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the upstream is cut and its proxy can only be put back in service through 127.0.0.1, not through %s", s.restHost),
			Check: "run `mise run nexus-bench:restore-upstream` on the machine that runs the bench, then up again",
		}
	}
	return true, nil
}

// provision provisions a bench that is already running.
func (s *session) provision() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	s.warnIfClearText()
	pre, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpProvision)
	if err != nil {
		return s.fail(err)
	}
	provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	return s.writeDescriptor(nexusbench.DeployResult{NodeIP: pre.NodeIP}, provisioned, s.keptDataset())
}

// keptDataset returns the data set of the code when the descriptor on disk is the
// descriptor of the same bench (namespace, context and upstream URL unchanged) and
// lists exactly that data set: the data set is fixed in the code, so what the file
// holds is compared to it and never copied. A file that disagrees, or is of another
// bench, counts as no data set, and the command says so. A descriptor that cannot
// be read (none, or schema 1), or that lists no image, has nothing to keep.
func (s *session) keptDataset() nexusbench.SeedResult {
	prev, err := nexusbench.LoadDescriptor(s.descriptorPath())
	if err != nil || len(prev.Dataset) == 0 {
		return nexusbench.SeedResult{}
	}
	code := nexusbench.SeedResult{Images: nexusbench.Dataset()}
	want := nexusbench.BuildDescriptor(s.p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, code).Dataset
	if prev.Namespace == s.p.Namespace && prev.KubeContext == s.p.Context && prev.Upstream.URL == s.p.UpstreamURL &&
		reflect.DeepEqual(prev.Dataset, want) {
		return code
	}
	line := "provision: the descriptor now lists no data set"
	if s.p.UpstreamIsBench() {
		line += "; run mise run nexus-bench:seed"
	}
	_, _ = fmt.Fprintln(s.stdout, line)
	return nexusbench.SeedResult{}
}

// seed puts the data set in a bench that up already provisioned, then writes the
// descriptor again. Seed has no data of its own about Nexus: the version, the
// edition, the EULA consent and the hosts (and so the URLs that depend on them)
// come from the descriptor of the previous run, which is read before anything is
// copied. The preflight of a seed does not read the node, so it has no address to
// give.
func (s *session) seed() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	s.warnIfClearText()
	prev, err := s.previousDescriptor()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpSeed); err != nil {
		return s.fail(err)
	}
	seeded, err := s.runSeed(runner, store, d)
	if err != nil {
		return s.fail(err)
	}
	provisioned := nexusbench.ProvisionResult{NexusVersion: prev.NexusVersion, Edition: prev.Edition, EULAAccepted: prev.EULAAccepted}
	return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
}

// previousDescriptor reads the descriptor of the previous run. Without a readable
// descriptor of schema 2 (missing, schema 1, not JSON), or with the descriptor of
// another bench (namespace or context), the bench was not provisioned by this
// build for these parameters, and the answer is to run up.
func (s *session) previousDescriptor() (nexusbench.Descriptor, error) {
	path := s.descriptorPath()
	prev, err := nexusbench.LoadDescriptor(path)
	var be *nexusbench.BenchError
	switch {
	case err == nil:
	case errors.As(err, &be):
		return prev, err
	default:
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: "there is no readable descriptor of a provisioned bench (" + err.Error() + ")",
			Check: "run `mise run nexus-bench:up` first: the seed completes the descriptor that up writes",
			Err:   err,
		}
	}
	if prev.Namespace != s.p.Namespace || prev.KubeContext != s.p.Context {
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the descriptor %s describes namespace %q on context %q, not namespace %q on context %q", path, prev.Namespace, prev.KubeContext, s.p.Namespace, s.p.Context),
			Check: "run `mise run nexus-bench:up` for this bench first: the seed completes the descriptor that up writes",
		}
	}
	if err := nexusbench.ValidateDescriptorHosts(prev.Hosts); err != nil {
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the descriptor %s cannot be trusted: %s", path, err),
			Check: "run `mise run nexus-bench:up` for this bench first: it writes the descriptor again",
		}
	}
	return prev, nil
}

// down deletes the bench namespace. The descriptor is left alone: it is the
// versioned description of the bench, not part of one instance.
func (s *session) down() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	if err := s.d.destroy(s.ctx, runner, s.d.clock, store, s.p, s.stdout); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// descriptorPath is where the descriptor is read and written.
func (s *session) descriptorPath() string {
	if s.p.DescriptorPath != "" {
		return s.p.DescriptorPath
	}
	return nexusbench.DescriptorPath()
}

// writeDescriptor writes the descriptor of a bench that was provisioned and, for
// up and seed, seeded. It is called after a step that succeeded only: a partial
// result is never described.
func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult, seeded nexusbench.SeedResult) int {
	path := s.descriptorPath()
	if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned, seeded)); err != nil {
		return s.fail(err)
	}
	_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
	if !describesDefaultBench(s.p) {
		s.warn("descriptor.json now describes a non-default bench; do not commit it")
	}
	return exitOK
}

// describesDefaultBench tells whether p is the bench the versioned descriptor
// describes. The timeouts, the paths and the EULA consent do not change what
// the bench is, so they are left out.
func describesDefaultBench(p nexusbench.Params) bool {
	normalize := func(p nexusbench.Params) nexusbench.Params {
		p.Timeout, p.DeleteTimeout = 0, 0
		p.SecretsPath, p.DescriptorPath = "", ""
		p.AcceptEULA = false
		if len(p.Hosts) == 0 {
			p.Hosts = nil
		}
		return p
	}
	return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
}

